// 4-wide combo engine: board ops, SRS, placement enumeration (BFS w/ tucks+spins),
// and lookahead search that maximizes combo continuation over the visible queue.
(function (global) {
  const W = 4, H = 25, FULL = (1 << W) - 1;

  // base rotation-0 shapes; other rotations generated by CW rotation in an NxN box
  const BASE = {
    I: { n: 4, c: [[0, 1], [1, 1], [2, 1], [3, 1]] },
    O: { n: 3, c: [[1, 0], [2, 0], [1, 1], [2, 1]] },
    T: { n: 3, c: [[1, 0], [0, 1], [1, 1], [2, 1]] },
    S: { n: 3, c: [[1, 0], [2, 0], [0, 1], [1, 1]] },
    Z: { n: 3, c: [[0, 0], [1, 0], [1, 1], [2, 1]] },
    J: { n: 3, c: [[0, 0], [0, 1], [1, 1], [2, 1]] },
    L: { n: 3, c: [[2, 0], [0, 1], [1, 1], [2, 1]] },
  };
  const SHAPES = {};
  for (const id in BASE) {
    const { n, c } = BASE[id];
    if (id === 'O') { SHAPES[id] = [c, c, c, c]; continue; }
    const rots = [c];
    for (let r = 1; r < 4; r++) rots.push(rots[r - 1].map(([x, y]) => [n - 1 - y, x]));
    SHAPES[id] = rots;
  }

  // SRS kick tables, converted to y-down grid coords (y sign flipped vs guideline tables)
  const JK = {
    '01': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
    '10': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
    '12': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
    '21': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
    '23': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
    '32': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
    '30': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
    '03': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
  };
  const IK = {
    '01': [[0, 0], [-2, 0], [1, 0], [-2, 1], [1, -2]],
    '10': [[0, 0], [2, 0], [-1, 0], [2, -1], [-1, 2]],
    '12': [[0, 0], [-1, 0], [2, 0], [-1, -2], [2, 1]],
    '21': [[0, 0], [1, 0], [-2, 0], [1, 2], [-2, -1]],
    '23': [[0, 0], [2, 0], [-1, 0], [2, -1], [-1, 2]],
    '32': [[0, 0], [-2, 0], [1, 0], [-2, 1], [1, -2]],
    '30': [[0, 0], [1, 0], [-2, 0], [1, 2], [-2, -1]],
    '03': [[0, 0], [-1, 0], [2, 0], [-1, -2], [2, 1]],
  };
  const F180 = [[0, 0], [0, -1], [0, 1], [-1, 0], [1, 0]];

  function fits(rows, id, x, y, r) {
    for (const [cx, cy] of SHAPES[id][r]) {
      const ax = x + cx, ay = y + cy;
      if (ax < 0 || ax >= W || ay >= H) return false;
      if (ay >= 0 && ((rows[ay] >> ax) & 1)) return false;
    }
    return true;
  }

  function tryRotate(rows, id, x, y, r, dir) {
    if (id === 'O') return null;
    const to = dir === 'CW' ? (r + 1) & 3 : dir === 'CCW' ? (r + 3) & 3 : (r + 2) & 3;
    const ks = dir === 'F' ? F180 : (id === 'I' ? IK : JK)['' + r + to];
    for (const [dx, dy] of ks) if (fits(rows, id, x + dx, y + dy, to)) return { x: x + dx, y: y + dy, r: to };
    return null;
  }

  function cellsOf(id, x, y, r) { return SHAPES[id][r].map(([cx, cy]) => [x + cx, y + cy]); }

  function clearRows(rows) {
    const out = []; let cleared = 0;
    for (let y = 0; y < H; y++) { if (rows[y] === FULL) cleared++; else out.push(rows[y]); }
    while (out.length < H) out.unshift(0);
    return { rows: out, cleared };
  }

  function buildPath(seen, key) {
    const toks = []; let k = key;
    while (k) { const e = seen.get(k); if (!e || !e.move) break; toks.push(e.move); k = e.prev; }
    toks.reverse();
    const out = [];
    for (const t of toks) {
      if (t === 'D') { if (out[out.length - 1] !== 'D') out.push('D'); }
      else out.push(t);
    }
    while (out[out.length - 1] === 'D') out.pop(); // trailing drop implied by hard drop
    return out;
  }

  // all reachable lock positions from spawn, incl. tucks and spins
  function placements(rows, id) {
    if (!fits(rows, id, 0, 0, 0)) return [];
    const seen = new Map(); const q = [{ x: 0, y: 0, r: 0 }];
    seen.set('0,0,0', { move: null, prev: null });
    const locks = new Map();
    while (q.length) {
      const s = q.shift(); const skey = s.x + ',' + s.y + ',' + s.r;
      if (!fits(rows, id, s.x, s.y + 1, s.r)) {
        const cells = cellsOf(id, s.x, s.y, s.r);
        const ck = cells.map(c => c[0] + ':' + c[1]).sort().join('|');
        if (!locks.has(ck)) {
          let lockout = false; const nr = rows.slice();
          for (const [ax, ay] of cells) { if (ay < 0) lockout = true; else nr[ay] |= (1 << ax); }
          const { rows: cr, cleared } = clearRows(nr);
          locks.set(ck, { id, x: s.x, y: s.y, r: s.r, cells, rows: cr, cleared, lockout, path: buildPath(seen, skey) });
        }
      }
      const cand = [];
      const cw = tryRotate(rows, id, s.x, s.y, s.r, 'CW'); if (cw) cand.push(['CW', cw]);
      const ccw = tryRotate(rows, id, s.x, s.y, s.r, 'CCW'); if (ccw) cand.push(['CCW', ccw]);
      const f = tryRotate(rows, id, s.x, s.y, s.r, 'F'); if (f) cand.push(['F', f]);
      if (fits(rows, id, s.x - 1, s.y, s.r)) cand.push(['L', { x: s.x - 1, y: s.y, r: s.r }]);
      if (fits(rows, id, s.x + 1, s.y, s.r)) cand.push(['R', { x: s.x + 1, y: s.y, r: s.r }]);
      if (fits(rows, id, s.x, s.y + 1, s.r)) cand.push(['D', { x: s.x, y: s.y + 1, r: s.r }]);
      for (const [m, ns] of cand) {
        const k = ns.x + ',' + ns.y + ',' + ns.r;
        if (!seen.has(k)) { seen.set(k, { move: m, prev: skey }); q.push(ns); }
      }
    }
    return [...locks.values()].filter(p => !p.lockout);
  }

  function evalBoard(rows) {
    let holes = 0, bump = 0, filled = 0; const hs = [];
    for (let x = 0; x < W; x++) {
      let top = -1;
      for (let y = 0; y < H; y++) if ((rows[y] >> x) & 1) { top = y; break; }
      hs.push(top < 0 ? 0 : H - top);
      if (top >= 0) for (let y = top + 1; y < H; y++) if (!((rows[y] >> x) & 1)) holes++;
    }
    for (let y = 0; y < H; y++) {
      const r = rows[y];
      filled += (r & 1) + ((r >> 1) & 1) + ((r >> 2) & 1) + ((r >> 3) & 1);
    }
    for (let x = 0; x < W - 1; x++) bump += Math.abs(hs[x] - hs[x + 1]);
    const maxh = Math.max(hs[0], hs[1], hs[2], hs[3]);
    return -holes * 120 - bump * 8 - maxh * 6 - Math.abs(filled - 3) * 10;
  }

  // lookahead: each combo-continuing clear is worth 1000; combo-breaking moves
  // still searched (damped) so it can rebuild residue if the chain is forced dead
  function hashRows(rows) {
    let s = '';
    for (let y = 0; y < H; y++) s += rows[y].toString(16);
    return s;
  }

  // caches persist across searchBest calls — consecutive hints share most positions
  const PCACHE = new Map(), ECACHE = new Map();
  function getPlacements(rows, rkey, id) {
    const k = rkey + id;
    let p = PCACHE.get(k);
    if (!p) {
      if (PCACHE.size > 60000) PCACHE.clear();
      p = placements(rows, id);
      for (const pl of p) { pl.rkey = hashRows(pl.rows); }
      PCACHE.set(k, p);
    }
    return p;
  }
  function getEval(rows, rkey) {
    let e = ECACHE.get(rkey);
    if (e === undefined) {
      if (ECACHE.size > 120000) ECACHE.clear();
      e = evalBoard(rows);
      ECACHE.set(rkey, e);
    }
    return e;
  }

  // horizon robustness: how many of the 7 piece types have a combo-continuing
  // placement from this residue — punishes leaving a shape only 2 pieces can clear
  const RCACHE = new Map();
  const ALL_IDS = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
  function clearability(rows, rkey) {
    let n = RCACHE.get(rkey);
    if (n === undefined) {
      if (RCACHE.size > 60000) RCACHE.clear();
      n = 0;
      for (const id of ALL_IDS) if (getPlacements(rows, rkey, id).some(p => p.cleared > 0)) n++;
      RCACHE.set(rkey, n);
    }
    return n;
  }

  const BEAM_CLEAR = [8, 8, 6, 6, 5, 5], BEAM_OTHER = [3, 2, 2, 2, 1, 1];

  // safeCheck?: (rowsAfter, holdUsed) => bool — membership in precomputed
  // provably-safe combo states; safe clears get a bonus so the AI enters and
  // never leaves the safe orbit when one is reachable
  function searchBest(rows, curId, nextIds, holdId, canHold, safeCheck) {
    const pieces = [curId, ...nextIds].slice(0, 6);
    const memo = new Map();

    function options(idx, hold) {
      const o = [];
      if (idx < pieces.length) {
        o.push({ piece: pieces[idx], nIdx: idx + 1, nHold: hold, holdUsed: false });
        if (hold) o.push({ piece: hold, nIdx: idx + 1, nHold: pieces[idx], holdUsed: true });
        else if (idx + 1 < pieces.length) o.push({ piece: pieces[idx + 1], nIdx: idx + 2, nHold: pieces[idx], holdUsed: true });
      }
      return o;
    }

    function nodeScore(rows, rkey, idx, hold) {
      const opts = options(idx, hold);
      if (!opts.length) return getEval(rows, rkey) * 0.01 + clearability(rows, rkey) * 30; // horizon
      const key = rkey + ';' + idx + ';' + (hold || '-');
      if (memo.has(key)) return memo.get(key);
      const clears = [], others = [];
      for (const o of opts) for (const p of getPlacements(rows, rkey, o.piece)) (p.cleared > 0 ? clears : others).push({ p, o });
      let best = -1e9;
      if (clears.length) {
        clears.sort((a, b) => getEval(b.p.rows, b.p.rkey) - getEval(a.p.rows, a.p.rkey));
        for (const { p, o } of clears.slice(0, BEAM_CLEAR[Math.min(idx, 5)])) best = Math.max(best, 1000 + nodeScore(p.rows, p.rkey, o.nIdx, o.nHold));
      } else if (others.length) {
        others.sort((a, b) => getEval(b.p.rows, b.p.rkey) - getEval(a.p.rows, a.p.rkey));
        for (const { p, o } of others.slice(0, BEAM_OTHER[Math.min(idx, 5)])) best = Math.max(best, getEval(p.rows, p.rkey) * 0.01 + 0.4 * nodeScore(p.rows, p.rkey, o.nIdx, o.nHold));
      } else best = -5000; // topped out
      memo.set(key, best);
      return best;
    }

    const tops = [{ piece: pieces[0], nIdx: 1, nHold: holdId, holdUsed: false }];
    if (canHold) {
      if (holdId) tops.push({ piece: holdId, nIdx: 1, nHold: pieces[0], holdUsed: true });
      else if (pieces[1]) tops.push({ piece: pieces[1], nIdx: 2, nHold: pieces[0], holdUsed: true });
    }
    let bestAct = null;
    const rootKey = hashRows(rows);
    for (const o of tops) {
      for (const p of getPlacements(rows, rootKey, o.piece)) {
        const child = nodeScore(p.rows, p.rkey, o.nIdx, o.nHold);
        const s = p.cleared > 0 ? 1000 + child : getEval(p.rows, p.rkey) * 0.01 + 0.4 * child;
        if (!bestAct || s > bestAct.score) bestAct = { ...p, holdUsed: o.holdUsed, score: s, chain: Math.max(0, Math.floor((s + 500) / 1000)) };
      }
    }
    return bestAct;
  }

  // ---- exact combo-survival DP ----
  // states: set of (rows, hold) reachable while clearing a line with EVERY piece
  // of seq in order. `first` carries the move that started each surviving line.
  const DP_CAP = 240;
  // st.nh: the previous piece was hold-only, so the piece now in hand can't be held again
  const dpKey = s => hashRows(s.rows) + ';' + (s.hold || '-') + (s.nh ? '!' : '');
  function dpRun(states, seq, canHoldFirst) {
    let cur = new Map(states.map(s => [dpKey(s), s]));
    for (let i = 0; i < seq.length; i++) {
      const p = seq[i], next = new Map();
      const allowHold = canHoldFirst || i > 0;
      for (const st of cur.values()) {
        const rkey = hashRows(st.rows);
        for (const pl of getPlacements(st.rows, rkey, p)) if (pl.cleared > 0) {
          const k = pl.rkey + ';' + (st.hold || '-');
          if (!next.has(k)) next.set(k, { rows: pl.rows, hold: st.hold, first: st.first || { holdUsed: false, holdOnly: false, pl } });
        }
        if (allowHold && !st.nh) {
          if (st.hold) {
            for (const pl of getPlacements(st.rows, rkey, st.hold)) if (pl.cleared > 0) {
              const k = pl.rkey + ';' + p;
              if (!next.has(k)) next.set(k, { rows: pl.rows, hold: p, first: st.first || { holdUsed: true, holdOnly: false, pl } });
            }
          } else {
            const k = rkey + ';' + p + '!'; // hold the piece, place nothing (combo unaffected); next piece can't be held
            if (!next.has(k)) next.set(k, { rows: st.rows, hold: p, nh: true, first: st.first || { holdOnly: true } });
          }
        }
      }
      if (!next.size) return null;
      let arr = [...next.values()];
      if (arr.length > DP_CAP) {
        arr.sort((a, b) => getEval(b.rows, hashRows(b.rows)) - getEval(a.rows, hashRows(a.rows)));
        arr = arr.slice(0, DP_CAP);
      }
      cur = new Map(arr.map(s => [dpKey(s), s]));
    }
    return [...cur.values()];
  }
  function dpPrefix(rows, holdId, seq, canHold = true) {
    return dpRun([{ rows, hold: holdId || null, first: null }], seq, canHold);
  }
  function dpExtendSurvives(states, seq) { return !!dpRun(states, seq, true); }
  function comboSurvives(rows, holdId, seq, canHold = true) { return !!dpPrefix(rows, holdId, seq, canHold); }
  // first move of the surviving line whose endpoint residue evals best; null if doomed
  function bestSurvivingMove(rows, holdId, seq, canHold = true) {
    const fin = dpPrefix(rows, holdId, seq, canHold);
    if (!fin) return null;
    let best = null;
    for (const s of fin) { const e = getEval(s.rows, hashRows(s.rows)); if (!best || e > best.e) best = { e, s }; }
    return best.s.first;
  }

  // ---- move audit ----
  // How many pieces of seq (index 0 = current) does the combo survive from `state`,
  // having already consumed seq[0..from)? depth === seq.length means survived all.
  function chainDepth(state, seq, from) {
    let cur = [state], d = from;
    while (d < seq.length) {
      const nxt = dpRun(cur, [seq[d]], true);
      if (!nxt) break;
      cur = nxt; d++;
    }
    return { depth: d, states: cur };
  }

  // Which pieces can come right after a visible 7-bag run? p0 = bag offset (0..6) of seq[0].
  // Bag-mates of the unseen piece that already appeared are ruled out; at the end of a bag it is fully determined.
  function bagNext(seq, p0) {
    const ph = (p0 + seq.length) % 7; // bag-mates that came before the unseen piece
    const seen = new Set(seq.slice(seq.length - ph));
    return ALL_IDS.filter(id => !seen.has(id));
  }
  // bag offset of the piece in hand, given how many pieces are still queued behind it
  const bagOffset = queueLen => (((7 - queueLen % 7) % 7) + 6) % 7;

  // After surviving the whole view, how many of the possible unseen pieces can ONE line still clear?
  // (the line is fixed before the piece appears, so it can't adapt to it)
  const COVER_STATES = 48;
  function coverOf(states, poss) {
    const top = states.length > COVER_STATES
      ? states.slice().sort((a, b) => getEval(b.rows, hashRows(b.rows)) - getEval(a.rows, hashRows(a.rows))).slice(0, COVER_STATES)
      : states;
    let best = { n: -1, missed: poss };
    for (const st of top) {
      const missed = poss.filter(p => !dpRun([st], [p], true));
      if (poss.length - missed.length > best.n) best = { n: poss.length - missed.length, missed };
      if (!missed.length) break;
    }
    return best;
  }

  // Judge a played move against every alternative, using only the pieces the player can see.
  // chosen: { holdUsed, rows: board after lock + clear, cleared }
  // opt: { p0 (bag offset of seq[0]; enables the unseen-piece check), canHold (default true) }
  //   forced   nothing clears            noclear  dropped without clearing
  //   doomed   a longer-surviving move existed (depth = how far ahead you had to look)
  //   deadend  every move dies inside the view: unavoidable, not a mistake
  //   risky    survives the view, but another move survives more of the possible unseen pieces
  //   safe     survives the view and is as robust to the unseen piece as any move
  function auditMove(rows, holdId, seq, chosen, opt = {}) {
    const rkey = hashRows(rows), full = seq.length;
    const poss = opt.p0 === undefined ? null : bagNext(seq, opt.p0);
    // every legal first move that clears: hold route + placement, with how long the combo then survives
    const routes = [{ piece: seq[0], hold: holdId || null, used: false, from: 1 }];
    if (opt.canHold !== false) {
      if (holdId) routes.push({ piece: holdId, hold: seq[0], used: true, from: 1 });
      else if (seq[1]) routes.push({ piece: seq[1], hold: seq[0], used: true, from: 2 });
    }
    const opts = new Map();
    for (const r of routes) {
      for (const pl of getPlacements(rows, rkey, r.piece)) {
        if (pl.cleared === 0) continue;
        const k = pl.rkey + ';' + (r.hold || '-') + ';' + r.from;
        if (opts.has(k)) continue;
        const ch = chainDepth({ rows: pl.rows, hold: r.hold, first: null }, seq, r.from);
        const o = { holdUsed: r.used, pl, depth: ch.depth, cover: 0, e: getEval(pl.rows, pl.rkey) };
        if (poss && ch.depth === full) o.cover = coverOf(ch.states, poss).n;
        opts.set(k, o);
      }
    }
    let best = null;
    for (const o of opts.values()) {
      if (!best || o.depth > best.depth || (o.depth === best.depth && (o.cover > best.cover || (o.cover === best.cover && o.e > best.e)))) best = o;
    }
    let bestDepth = best ? best.depth : 0, bestCover = best ? best.cover : 0;

    let depth = 0, cover = 0, missed = [];
    if (chosen.cleared > 0) {
      const from = chosen.holdUsed && !holdId ? 2 : 1;
      const hold = chosen.holdUsed ? seq[0] : (holdId || null);
      const ch = chainDepth({ rows: chosen.rows, hold, first: null }, seq, from);
      depth = ch.depth;
      if (poss && depth === full) { const c = coverOf(ch.states, poss); cover = c.n; missed = c.missed; }
      // DP pruning can hide a line; the played move is proof it exists
      if (depth > bestDepth) { bestDepth = depth; bestCover = cover; best = null; }
      else if (depth === bestDepth && cover > bestCover) { bestCover = cover; best = null; }
    }

    let verdict;
    if (bestDepth === 0) verdict = 'forced';
    else if (!chosen.cleared) verdict = 'noclear';
    else if (depth < bestDepth) verdict = 'doomed';
    else if (bestDepth < full) verdict = 'deadend';
    else if (cover < bestCover) verdict = 'risky';
    else verdict = 'safe';

    // depths at which some clearing alternative would have died: the lookahead tests this decision held
    const traps = new Set([...opts.values()].map(o => o.depth).filter(d => d < bestDepth));
    if (verdict === 'doomed') traps.add(depth);
    const covTrap = !!poss && [...opts.values()].some(o => o.depth === full && o.cover < bestCover);
    return {
      verdict, bestDepth, depth, full, cover, bestCover, missed, covTrap, nposs: poss ? poss.length : 0,
      killer: verdict === 'doomed' ? seq[depth] : null,
      traps: [...traps].sort((a, b) => a - b),
      best: best ? { holdUsed: best.holdUsed, pl: best.pl } : null,
    };
  }

  // the move the coach would play: longest survival in view, then most robust to the unseen piece, then board eval
  function coachHint(rows, holdId, seq, canHold, p0) {
    const a = auditMove(rows, holdId, seq, { cleared: 0, rows, holdUsed: false }, { canHold, p0 });
    return a.best ? { ...a.best, depth: a.bestDepth, full: a.full, cover: a.bestCover, nposs: a.nposs } : null;
  }

  const E = { W, H, FULL, SHAPES, fits, tryRotate, cellsOf, clearRows, placements, evalBoard, searchBest, comboSurvives, bestSurvivingMove, dpPrefix, dpExtendSurvives, auditMove, coachHint, bagNext, bagOffset };
  if (typeof module !== 'undefined' && module.exports) module.exports = E;
  else global.Engine = E;
})(typeof window !== 'undefined' ? window : globalThis);
